"""Balanced edition of MAR3023 Exam 3 Chapter 2 Part 1 (2026-11-04), cut from a Full
file (either variant: the prose is the same). python balanced2.py FULL.html OUT.html"""
import sys
src, out = sys.argv[1:3]; t = open(src, encoding="utf-8").read()
def rep(prefix, new, tag="p"):
    global t
    i = t.find(prefix); assert i >= 0, prefix[:50]; assert t.find(prefix, i + 1) < 0, "not unique: " + prefix[:50]
    s = t.rfind("<" + tag, 0, i); e = t.find("</" + tag + ">", i) + len(tag) + 3
    assert s >= 0 and t.find("</" + tag + ">", s) == e - len(tag) - 3, prefix[:50]
    t = t[:s] + new + t[e:]
rep("<strong>For-profit organizations</strong> (business firms)", "<li><strong>For-profit organizations</strong> (business firms) are privately owned and serve customers to earn a profit—total revenues minus total expenses. Examples: <strong>Nike, Target, and Spotify</strong>.</li>", "li")
rep("<strong>Government agencies</strong> are public organizations", "<li><strong>Government agencies</strong> are public organizations—federal, state, county, or city—that serve citizens, such as the <strong>U.S. Census Bureau</strong>.</li>", "li")
rep("<strong>Corporate level</strong> – This is the highest level", "<li><strong>Corporate level</strong> – The highest level, where top management sets overall strategy and the CEO keeps every division working toward the same mission. Many firms now have a Chief Marketing Officer (CMO), who develops marketing strategy and sees that it is carried out.</li>", "li")
rep("<strong>Strategic Business Unit (SBU) level</strong>", "<li><strong>Strategic Business Unit (SBU) level</strong> – Managers focus on specific product lines or markets. An SBU is a division or subsidiary offering related products to a defined group of customers; Procter &amp; Gamble and Disney have many, while smaller firms fold this level into the corporate one.</li>", "li")
rep("<strong>Functional level</strong> – Specialists in areas like marketing", "<li><strong>Functional level</strong> – Specialists in marketing, finance, operations, and so on turn strategy into action. A <strong>cross-functional team</strong> brings people from different departments together to share responsibility for a common objective, such as launching a new product.</li>", "li")
rep("<strong>Organizational purpose</strong> explains why the organization exists", "<li><strong>Organizational purpose</strong> explains why the organization exists, the problems it aims to solve, and how it wants to be viewed; it is the base for everything else.</li>", "li")
rep("<strong>Core values</strong> are the timeless principles", "<li><strong>Core values</strong> are the timeless principles, set by founders or top leaders, that define how the organization behaves—its \"heart and soul.\" They do not bend to short-term pressure, and strong leaders communicate them clearly to employees, customers, and other stakeholders.</li>", "li")
rep("<strong>Mission</strong> describes the organization's scope", "<li><strong>Mission</strong> describes the organization's scope—its customers, markets, and offerings. Modern mission statements often include social responsibility.</li>", "li")
rep("<em>The firm's specific goals</em> – <strong>Goals</strong>", "<li><em>The firm's specific goals</em> – <strong>Goals</strong> or <strong>objectives</strong> convert the mission into targeted levels of performance, often with deadlines, at the corporate, business unit, and functional levels, with lower-level goals feeding higher ones. Goals can concern profit, sales, market share, quality, customer satisfaction, employee welfare, or social responsibility.</li>", "li")
rep("A <strong>marketing dashboard</strong> is the visual display", "<p>A <strong>marketing dashboard</strong> is the visual display of the essential information related to achieving a marketing objective, now fed real-time data by business-intelligence and AI tools. Like a car's dashboard, it shows a manager what the next decision needs.</p>")
rep("A <strong>corporate mission</strong> is a statement that clearly defines the markets", "<p>A <strong>corporate mission</strong> is a statement that defines the markets in which a firm competes and the value it delivers to customers: whom the firm serves and how it adds value for them, which requires understanding its core competencies. Some examples:</p>")
rep("<em>Google</em> – \"Organizing the world's information", "<li><em>Google</em> – \"Organizing the world's information and making it universally accessible and useful.\" The market is everyone; the value is the ranking of information—paid for by scanning what you write and search for, which is also a privacy concern.</li>", "li")
rep("<em>CVS Health</em> – \"Helping people on a path to better health.\"", "<li><em>CVS Health</em> – \"Helping people on a path to better health.\" The value is access to medicines and health goods; the statement had teeth, since it is why CVS stopped selling tobacco at an immediate cost to profit.</li>", "li")
rep("<em>Boston Beer Company</em>", "<li><em>Boston Beer Company</em> – \"We make the best beer in America.\" The market is Americans who want a premium craft beer, not every beer drinker, so it does not see itself competing with Bud or Miller.</li>", "li")
rep("<em>TikTok</em> – \"Inspire creativity and bring joy.\"", "<li><em>TikTok</em> – \"Inspire creativity and bring joy.\"</li>", "li")
rep("<em>Tesla</em> – \"To accelerate the world's transition to sustainable energy.\"", "<li><em>Tesla</em> – \"To accelerate the world's transition to sustainable energy.\" Its business is batteries and energy storage; cars are one application.</li>", "li")
rep("The Louisville Redbirds (now the Louisville Bats", "<p>The Louisville Redbirds (now the Louisville Bats, a Triple-A team) show how hard the \"whom and how\" question is. Fans said they came for baseball, cheap tickets, autographs from future stars, good food, fireworks, and a bring-your-own-cooler picnic area; the common thread became the mission: affordable family entertainment built around baseball.</p>")
rep("Google restructured under Alphabet to prevent its mission statement", "<p>Google restructured under Alphabet, and Facebook renamed itself Meta, so that their missions stayed clear as their holdings grew well beyond the original business.</p>")
rep("<strong>Railroads:</strong> Once dominant in U.S. transportation", "<li><strong>Railroads:</strong> Once dominant, they declined because they saw themselves as \"railroads,\" not \"transportation providers,\" and were caught flat-footed when 1930s roads gave shippers and travelers cars and trucks.</li>", "li")
rep("<strong>Pickett Slide Rules:</strong> Pickett held 80–90%", "<li><strong>Pickett Slide Rules:</strong> Pickett held 80–90% of the slide-rule market (its rules flew on the Apollo missions) and dismissed early electronic calculators as bulky—until they became small, cheap, and capable. A mission of \"making complex calculations easier\" could have evolved with the technology.</li>", "li")
rep("A mission can also fail by being so broad that it guides nothing.", "<p>A mission can also fail by being so broad that it guides nothing: Microsoft's \"Empower every person and organization on the planet to achieve more\" covers everything and says nothing. The goal is a statement that steers without being myopic or meaningless, as Nike's does (inspiration and innovation for every athlete—and if you have a body, you are an athlete).</p>")
rep("A <strong>corporate goal</strong> is a specific, measurable objective", "<p>A <strong>corporate goal</strong> is a specific, measurable objective used to assess performance—target revenue, profit, sales, market share, quality, or customer satisfaction. Goals express an aspiration and provide a yardstick for whether the firm is on track. Two techniques for setting them are (1) portfolio analysis and (2) diversification analysis.</p>")
rep("The Boston Consulting Group (BCG) developed <strong>business portfolio analysis</strong>", "<p>The Boston Consulting Group (BCG) developed <strong>business portfolio analysis</strong> (or <strong>product portfolio analysis</strong>), which analyzes a firm's SBUs as a collection of separate investments. It rests on the product life cycle: every product eventually matures and declines, so a lasting firm needs products at different stages. The tool is the <strong>BCG growth-share matrix</strong>, which classifies products and business units on 2 dimensions:</p>")
rep("Consider the toothpaste market, where the raw market shares", "<p>In toothpaste, raw shares are Crest 32.8%, Colgate 22.3%, Arm &amp; Hammer 9.4%, and Aquafresh 8.2%. Colgate's RMS is 22.3 ÷ 32.8 = 0.68; Crest's is 32.8 ÷ 22.3 = 1.47. With the market growing only 4.6% per year, Crest is a cash cow and the other three are dogs: Crest keeps the brand going without heavy reinvestment and funds the next growth market, while a brand like Aquafresh must decide whether to sell or let it limp along.</p>")
rep("Now consider toothbrushes, a market growing 13.1% per year", "<p>Toothbrushes grow 13.1% per year, with raw shares of Oral-B 22.3%, Reach 17.6%, Colgate 16.0%, and Crest Complete 12.1%. Oral-B has the largest share, so its RMS exceeds 1: it is a star and the other three are question marks. Positions in a fast-growing market are tenuous; a question mark with a breakthrough can leapfrog the leader.</p>")
rep("Focusing on market growth rate—not just market size", "<p>Market growth rate, not just size, shows where opportunities are headed. In 2005 carbonated soft drinks were the largest U.S. beverage category per person, yet as consumers turned to healthier choices soft drinks shrank about 17% over 2001–2011 while bottled water surged about 55%; bottled water is now the beverage most adults drink regularly (63%, versus 56% for soft drinks). The roughly $3 billion the beverage market added from 2024 to 2025 came from non-alcoholic drinks, while alcohol is slipping and wine is roughly flat.</p>")
rep("<b>Market power increases due to barriers to entry</b>", "<li><b>Market power increases due to barriers to entry</b>. A dominant brand can direct its channel partners and set the prices others follow, and its customer loyalty makes it hard to displace, so a newcomer must be better than it would otherwise need to be.</li>", "li")
rep("Cost reductions come not only from economies of scale", "<p>Cost reductions come from economies of scale (buying in bulk, spreading fixed costs) and also from learning and technological improvement, which take ongoing research and process refinement.</p>")
rep("The pattern is a cousin of Moore's Law", "<p>The pattern is a cousin of Moore's Law: on a logarithmic scale, every computer since the 1945 ENIAC falls on one straight line.</p>")
rep("The U.S. smartphone market shows both forces at work.", "<p>The U.S. smartphone market shows both forces: Apple held roughly 60–69% of the market in 2024–25 despite premium prices, Samsung slipped from about 18% to 13%, and the rest stayed flat. Samsung is less troubled than that suggests, since it dominates other markets and supplies the screens in iPhones.</p>")
rep("Marketing managers must identify and leverage a competitive advantage", "<p>Marketing managers must identify and leverage a competitive advantage. Long-term success depends less on management tools than on strong strategy, execution, culture, and structure. A successful company typically shows:</p>")
rep("A successful company typically demonstrates:", "")
open(out, "w", encoding="utf-8").write(t); print(len(open(src, encoding="utf-8").read()), "->", len(t))
